using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class TimelineCanvasOperations:RefCounted
{
    private const float Header=34,LabelWidth=140;private readonly ActorTimelineOperations _timeline=new();private readonly ActorResourceSlotOperations _slots=new();
    private static RefCounted Model(Control owner)=>owner.Get("model").As<RefCounted>();private static GArray Clips(Control owner)=>Model(owner).Get("clips").AsGodotArray();private static GArray Actors(Control owner)=>Model(owner).Get("actors").AsGodotArray();private static double N(Control owner,string key)=>owner.Get(key).AsDouble();private static GArray List(Control owner,string key)=>owner.Get(key).AsGodotArray();
    public double magnetic_delta(Control owner,double delta,GArray moving,GArray excludedClips,GArray excludedKeys,bool keyframeView,bool includePlayhead)
    {
        if(!owner.Get("magnet_enabled").AsBool())return delta;var targets=new List<double>();if(includePlayhead)targets.Add(N(owner,"playhead"));var model=Model(owner);var clips=Clips(owner);var selected=keyframeView?_timeline.selected_actor(model):null;for(int i=0;i<clips.Count;i++){var clip=clips[i].As<Resource>();if(!_timeline.clip_is_visible(model,i)||excludedClips.Contains(clip.Get("id")))continue;if(keyframeView&&(selected==null||clip.Get("actor_id").AsString()!=selected.Get("id").AsString()))continue;double start=clip.Get("start_time").AsDouble();targets.Add(start);targets.Add(start+clip.Get("duration").AsDouble());}var actor=keyframeView?selected:_timeline.actor_for_id(model,model.Get("overlay_actor_id").AsString());if(actor!=null){var clip=_timeline.clip_for_actor_id(model,actor.Get("id").AsString());if(clip!=null){int index=clips.IndexOf(clip);if(keyframeView||index>=0&&_timeline.clip_is_visible(model,index)){if(keyframeView){targets.Add(clip.Get("start_time").AsDouble());targets.Add(clip.Get("start_time").AsDouble()+clip.Get("duration").AsDouble());}foreach(var item in actor.Get("animation_tracks").AsGodotArray()){var track=item.As<Resource>();if(!keyframeView&&!track.Get("path").AsStringArray().SequenceEqual(model.Get("overlay_path").AsStringArray()))continue;foreach(var keyValue in track.Get("keys").AsGodotArray()){var key=keyValue.As<Resource>();if(!excludedKeys.Contains(key.Get("id"))&&!excludedClips.Contains(clip.Get("id")))targets.Add(clip.Get("start_time").AsDouble()+(key.Get("time").AsDouble()-clip.Get("source_offset").AsDouble())/clip.Get("playback_speed").AsDouble());}}}}}double correction=8/N(owner,"pixels_per_second"),best=delta;foreach(var item in moving){double time=item.AsDouble();foreach(double target in targets){double distance=Math.Abs(target-(time+delta));if(distance<correction){correction=distance;best=target-time;}}}return best;
    }
    public double snapped_playhead(Control owner,double time,bool bypass,bool keyframeView){if(bypass)return Math.Max(0,time);if(owner.Get("snap_enabled").AsBool())time=Mathf.Snapped(time,.1);return Math.Max(0,time+magnetic_delta(owner,0,new GArray{time},new GArray(),new GArray(),keyframeView,false));}
    public int display_layer_count(Control owner){int count=_timeline.layer_count(Model(owner));var recording=owner.Get("recording_preview").AsGodotDictionary();if(recording.Count>0)count=Math.Max(count,recording["layer"].AsInt32()+1);foreach(var value in List(owner,"_asset_previews"))count=Math.Max(count,value.AsGodotDictionary()["layer"].AsInt32()+1);return count;}
    public void clear_asset_drag(Control owner){owner.Set("_asset_paths",Array.Empty<string>());List(owner,"_asset_templates").Clear();List(owner,"_asset_previews").Clear();owner.QueueRedraw();owner.EmitSignal("interaction_changed","");}
    public void ready(Control owner){owner.FocusMode=Control.FocusModeEnum.All;owner.ClipContents=true;owner.CustomMinimumSize=new Vector2(280,40);owner.MouseDefaultCursorShape=Control.CursorShape.Arrow;}
    public string[] dropped_paths(Variant data){var paths=new List<string>();if(data.VariantType==Variant.Type.Dictionary){var values=data.AsGodotDictionary();var collection=values.GetValueOrDefault("paths",values.GetValueOrDefault("files",new GArray()));if(collection.VariantType==Variant.Type.Array)foreach(var path in collection.AsGodotArray())paths.Add(_slots.path_from_drag(path.ToString()));else if(collection.VariantType==Variant.Type.PackedStringArray)foreach(string path in collection.AsStringArray())paths.Add(_slots.path_from_drag(path));}if(paths.Count==0){string path=_slots.path_from_drag(data);if(path.Length>0)paths.Add(path);}return paths.ToArray();}
    public double time_at(Control owner,double x)=>Math.Max(0,N(owner,"scroll_time")+(x-LabelWidth)/N(owner,"pixels_per_second"));
    public Rect2 clip_rect(Control owner,int index){var clip=Clips(owner)[index].As<Resource>();var state=owner.Get("_preview_states").AsGodotDictionary().GetValueOrDefault(clip.Get("id"),new Settings()).AsGodotDictionary();double time=state.GetValueOrDefault("start",clip.Get("start_time")).AsDouble(),duration=state.GetValueOrDefault("duration",clip.Get("duration")).AsDouble(),row=N(owner,"row_height"),margin=Math.Clamp(row*.12,2,4);int layer=state.GetValueOrDefault("layer",clip.Get("layer")).AsInt32();return new Rect2((float)(LabelWidth+(time-N(owner,"scroll_time"))*N(owner,"pixels_per_second")),(float)(Header+layer*row-N(owner,"scroll_rows")+margin),(float)(duration*N(owner,"pixels_per_second")),(float)Math.Max(row-margin*2,2));}
    public int layer_at(Control owner,double y)=>Math.Clamp((int)Math.Floor((y-Header+N(owner,"scroll_rows"))/N(owner,"row_height")),0,_timeline.layer_count(Model(owner))-1);
    public Vector2 fade_handle(Control owner,int index,bool incoming){var rect=clip_rect(owner,index);var actor=Actors(owner)[index].As<Resource>();double duration=Math.Clamp(actor.Get("values").AsGodotDictionary().GetValueOrDefault(incoming?"fade_in":"fade_out",0.0).AsDouble(),0,Clips(owner)[index].As<Resource>().Get("duration").AsDouble());float margin=Math.Min(6,rect.Size.X/2),inset=Math.Clamp((float)(duration*N(owner,"pixels_per_second")),margin,rect.Size.X-margin);return new Vector2(incoming?rect.Position.X+inset:rect.End.X-inset,rect.Position.Y+Math.Min(6,rect.Size.Y/2));}
    public void draw_fades(Control owner,int index,Rect2 rect){if(rect.Size.Y<16||rect.Size.X<20)return;foreach(bool incoming in new[]{true,false}){var point=fade_handle(owner,index,incoming);float edge=incoming?rect.Position.X:rect.End.X,bottom=rect.End.Y-2;if(point.X>=LabelWidth&&point.X<=owner.Size.X&&point.Y>=Header&&point.Y<=owner.Size.Y){owner.DrawLine(new Vector2(edge,bottom),point,new Color(1,.81f,.48f,.7f),1.5f);owner.DrawCircle(point,4,new Color("f4bf75"));owner.DrawCircle(point,4,new Color("513e28"),false,1);}}}
    public void cancel_fade(Control owner){var actor=owner.Get("_fade_actor").As<Resource>();if(actor==null)return;var definition=owner.Get("registry").AsGodotObject().Call("get_definition",new StringName("audio")).As<Resource>();_timeline.preview_property(Model(owner),actor,definition,owner.Get("_fade_key").AsStringName(),owner.Get("_fade_original"));owner.Set("_fade_actor",default(Variant));owner.EmitSignal("interaction_changed","");}
    public void cancel_drag(Control owner){cancel_fade(owner);owner.EmitSignal("interaction_changed","");owner.Set("drag_id","");List(owner,"_drag_ids").Clear();owner.Get("_drag_originals").AsGodotDictionary().Clear();owner.Get("_preview_states").AsGodotDictionary().Clear();if(owner.Get("scrubbing").AsBool()){owner.Set("scrubbing",false);owner.EmitSignal("time_selected",owner.Get("_scrub_origin"));}if(owner.Get("box_selecting").AsBool()){owner.Set("box_selecting",false);var ids=List(owner,"_box_base_selection");_timeline.set_selection(Model(owner),ids,ids.Count>0?ids[^1].AsString():"");ids.Clear();}owner.QueueRedraw();}
    public void begin_box_select(Control owner,Vector2 position,bool add,bool subtract){owner.Set("box_selecting",true);owner.Set("_box_start",position);owner.Set("_box_current",position);var ids=List(owner,"_box_base_selection");ids.Clear();foreach(var id in Model(owner).Get("selected_ids").AsGodotArray())ids.Add(id);update_box_selection(owner,add,subtract);owner.EmitSignal("interaction_changed","Esc cancels box select  •  Shift adds  •  Ctrl removes");owner.QueueRedraw();}
    public Rect2 selection_box(Control owner)=>new Rect2(owner.Get("_box_start").AsVector2(),owner.Get("_box_current").AsVector2()-owner.Get("_box_start").AsVector2()).Abs().Intersection(new Rect2(LabelWidth,Header,Math.Max(owner.Size.X-LabelWidth,0),Math.Max(owner.Size.Y-Header,0)));
    public void update_box_selection(Control owner,bool add,bool subtract){var hits=new GArray();var area=selection_box(owner);if(area.HasArea())for(int i=0;i<Clips(owner).Count;i++)if(_timeline.clip_is_visible(Model(owner),i)&&area.Intersects(clip_rect(owner,i),true))hits.Add(Clips(owner)[i].As<Resource>().Get("id"));var next=new GArray();if(add||subtract)foreach(var id in List(owner,"_box_base_selection"))next.Add(id);if(subtract){foreach(var id in hits)next.Remove(id);}else foreach(var id in hits)if(!next.Contains(id))next.Add(id);string primary=!subtract&&hits.Count>0?hits[^1].AsString():next.Count>0?next[^1].AsString():"";_timeline.set_selection(Model(owner),next,primary);}
    public Rect2 expanded_hit_rect(Rect2 rect)=>new(rect.Position-new Vector2(6,0),rect.Size+new Vector2(12,0));
    public int clip_hit_index(Control owner,Vector2 position){if(position.X<LabelWidth||position.Y<Header)return -1;var model=Model(owner);int primary=_timeline.index_of(model,model.Get("selected_id").AsString());if(_timeline.clip_is_visible(model,primary)&&expanded_hit_rect(clip_rect(owner,primary)).HasPoint(position))return primary;for(int i=Clips(owner).Count-1;i>=0;i--)if(i!=primary&&_timeline.clip_is_visible(model,i)&&expanded_hit_rect(clip_rect(owner,i)).HasPoint(position))return i;return -1;}
}
